import navData from '../../Constants/navItems'

import './Nav.css'

function Nav (setPath) {
    return(
        <div>
            <ul>
            {navData.map((elm, index)=>(
                <li key={index} on>{elm.name}</li>
            ))}
            </ul>
        </div>
    )
}

export default Nav
